<div class="heading"><div><div class="eyebrow">الوصول السريع</div><h1>أماكن جلوس الطلبة</h1><p>ابحث بالاسم أو الرمز ضمن العام الدراسي المختار.</p></div></div>
<section class="card"><form method="get" class="toolbar"><input type="hidden" name="page" value="lookup"><?php field('اسم الطالب أو رمزه','q',$_GET['q']??'','search');?><button>البحث عن المقعد</button></form>
<?php $query=trim($_GET['q']??'');if($query!==''):?>
<div class="table-wrap"><table><tr><th>الطالب / الرمز</th><th>المادة / الفترة</th><th>الموعد</th><th>القاعة / البناية</th><th>المقعد</th><th>الحالة</th><th>الخريطة</th></tr>
<?php $matches=rows('SELECT s.name,s.code,p.id AS period_id,p.name AS period_name,p.starts_at,p.status,b.name AS subject,r.code AS room,r.building,q.label,q.row_no,q.col_no FROM students s JOIN seating_assignments a ON a.student_id=s.id JOIN exam_periods p ON p.id=a.period_id JOIN exam_candidates c ON c.period_id=p.id AND c.student_id=s.id JOIN subjects b ON b.id=c.subject_id JOIN room_seats q ON q.id=a.seat_id JOIN rooms r ON r.id=q.room_id WHERE s.institution_id=? AND p.year_id=? AND (s.code LIKE ? OR s.name LIKE ?) ORDER BY s.name,p.starts_at',[inst(),year_id(),'%'.$query.'%','%'.$query.'%']);foreach($matches as $r):?><tr><td><?=h($r['name'])?><small><?=h($r['code'])?></small></td><td><?=h($r['subject'])?><small><?=h($r['period_name'])?></small></td><td><?=h($r['starts_at'])?></td><td><?=h($r['room'].' / '.$r['building'])?></td><td><?=h($r['label'])?><small>صف <?=(int)$r['row_no']?> / عمود <?=(int)$r['col_no']?></small></td><td><span class="badge <?=$r['status']==='draft'?'draft':''?>"><?=$r['status']==='approved'?'معتمد':'مسودة'?></span></td><td><a href="?page=exam&id=<?=(int)$r['period_id']?>">فتح الخريطة</a></td></tr><?php endforeach;if(!$matches):?><tr><td colspan="7" class="empty">لا يوجد مقعد موزع مطابق للبحث.</td></tr><?php endif;?></table></div><?php endif;?></section>
